import{existsSync}from'node:fs';import{pathToFileURL}from'node:url';import{resolve as pathResolve}from'node:path';
export async function resolve(specifier,context,nextResolve){let candidate;if(specifier.startsWith('$lib/'))candidate=pathToFileURL(pathResolve('apps/web/src/lib',specifier.slice(5))).href;else if(specifier.startsWith('.')&&context.parentURL?.startsWith('file:'))candidate=new URL(specifier,context.parentURL).href;if(candidate&&!/\.[a-z]+$/.test(new URL(candidate).pathname)&&existsSync(new URL(candidate+'.ts')))return nextResolve(candidate+'.ts',context);return nextResolve(candidate??specifier,context);}
